BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP-115-2-034','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2026-07-25。本題考精神衛生法強制社區治療項目。本法於 2022-12-14 全文修正（2024-12-14 施行，第五章強制社區治療及強制住院治療自 2026-08-01 施行），條次重新編排；本題考試時第五章尚未施行，修正前第46條所列項目為藥物治療、藥物之血液或尿液濃度檢驗、酒精或其他成癮物質篩檢及其他措施。現行第57條明列藥物治療、藥物之血液或尿液濃度檢驗、酒精或其他成癮物質篩檢、心理治療、復健治療及其他處置措施，不含「網絡介入」。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020030'),('SP106-1-02','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考精神衛生法強制住院之許可。考試時第41條規定強制鑑定後仍有全日住院治療必要，嚴重病人拒絕接受或無法表達時，應向中央主管機關精神疾病強制鑑定、強制社區治療審查會申請許可強制住院，故選(D)。本法於 2022-12-14 全文修正（2024-12-14 施行，第五章強制社區治療及強制住院治療自 2026-08-01 施行），條次重新編排，現行第59條改為由指定精神醫療機構向法院聲請裁定強制住院，現行第53條之審查會僅審查強制社區治療事項；依現行條文應為法院（選項(A)），選項(D)已不正確。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020030'),('SP107-2-27','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題考精神衛生法緊急安置後強制鑑定之期限。考試時第42條規定緊急安置期間不得逾五日，強制鑑定應自緊急安置之日起二日內完成，故選(B)。本法於 2022-12-14 全文修正（2024-12-14 施行，第五章強制社區治療及強制住院治療自 2026-08-01 施行），條次重新編排，現行第60條改為緊急安置期間為七日，強制鑑定應自緊急安置之次日起三日內完成；依現行條文應選(C)。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020030'),('SP108-2-35','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-07-27。本題考精神衛生法強制住院治療費用之負擔。考試時第26條規定嚴重病人依本法接受強制住院治療之費用由中央主管機關負擔；本法於 2022-12-14 全文修正（2024-12-14 施行，第五章強制社區治療及強制住院治療自 2026-08-01 施行），條次重新編排，現行第41條規定緊急安置、強制住院治療之費用由中央主管機關負擔，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020030'),('SP109-1-33','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-02-15。本題考精神衛生法病人保護規定。考試時第36條規定應向病人本人及其保護人說明病情；第37條規定精神照護機構經告知病人後得限制其活動之區域範圍、精神醫療機構得拘束病人身體於特定之保護設施內；第42條規定嚴重病人或其保護人得向法院聲請裁定停止緊急安置或強制住院，選項(D)「不得」聲請為錯誤。本法於 2022-12-14 全文修正（2024-12-14 施行，第五章強制社區治療及強制住院治療自 2026-08-01 施行），條次重新編排：現行第30條、第32條、第66條仍有相同規定，選項(D)仍錯誤；惟現行第31條改為精神照護機構須經病人同意，始得限制其居住場所或行動，並應於最小限制之必要範圍內為之，選項(B)「經告知病人後」即得限制之敘述已不符現行條文。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020030'),('SP110-1-30','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-02-06。本題考精神衛生法精神醫療照護業務。考試時第36條規定精神醫療機構應向病人本人及其保護人說明病情及應享有之權利，選項(D)「僅應向其保護人」說明為錯誤；第37條、第38條規定精神照護機構經告知病人後得限制其活動之區域範圍、精神醫療機構得拘束病人身體或限制其行動自由於特定之保護設施內、病情穩定時應辦理出院且不得無故留置病人。本法於 2022-12-14 全文修正（2024-12-14 施行，第五章強制社區治療及強制住院治療自 2026-08-01 施行），條次重新編排：現行第30條改為向本人及其家屬或保護人說明，選項(D)仍錯誤；現行第32條、第33條仍有拘束身體或限制行動自由及不得無故留置之規定；惟現行第31條改為精神照護機構須經病人同意，始得限制其居住場所或行動，選項(A)「經告知病人後」即得限制之敘述已不符現行條文。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020030'),('SP111-1-37','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-02-19。本題考精神衛生法精神衛生體系。考試時第11條規定由各級教育主管機關協助病人接受各級各類教育及建立友善支持學習環境，選項(A)「社政主管機關」為錯誤；勞工主管機關推動職場心理衛生（考試時第9條）、社區心理衛生中心（考試時第7條）及中央主管機關應會同中央社政、勞工及教育主管機關建立社區照顧、支持與復健體系（考試時第8條）均有規定。本法於 2022-12-14 全文修正（2024-12-14 施行，第五章強制社區治療及強制住院治療自 2026-08-01 施行），條次重新編排：現行第6條仍由教育主管機關負責，選項(A)仍錯誤；現行第7條、第28條仍有勞動主管機關與社區心理衛生中心之規定；惟修正前第8條之規定已不存在，現行第26條改由地方主管機關結合衛生、社政、民政、教育或勞動機關建立社區支持體系，第24條由中央主管機關獎勵、補助社區支持及復健相關服務，選項(D)已不符現行條文。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020030'),('SP115-1-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2026-02-07。本題考精神衛生法精神衛生服務體系。本法於 2022-12-14 全文修正（2024-12-14 施行，第五章強制社區治療及強制住院治療自 2026-08-01 施行），條次重新編排；本題考試時已適用修正後第19條（積極布建精神病人社區支持服務資源）、第21條（各級政府得設立或獎勵民間設立精神照護機構）及第22條（精神復健機構應置負責人一人，並得視需要置醫事人員或社會工作師；地方主管機關應定期督導考核，機構不得規避、妨礙或拒絕），各條公布後未再修正，考試時條文與現行條文相同；條文並未規定負責人不得由醫事人員擔任，選項(C)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020030'),('SW-104-1-23','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考精神衛生法社區治療及強制社區治療。考試時第45條規定強制社區治療期間不得逾六個月、第15條規定審查會「得」通知當事人或利害關係人到場說明、第26條規定強制社區治療費用不屬全民健康保險給付範圍者由中央主管機關負擔、第3條規定社區治療包括門診治療。本法於 2022-12-14 全文修正（2024-12-14 施行，第五章強制社區治療及強制住院治療自 2026-08-01 施行），條次重新編排：現行第54條、第53條、第41條、第3條仍有相同規定（審查會更名為精神疾病強制社區治療審查會，仍為「得」通知到場說明），選項(B)「應通知」仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020030'),('SW-106-1-20','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考精神衛生法精神疾病之定義。考試時第3條規定精神疾病範圍包括精神病、精神官能症、酒癮、藥癮及其他經中央主管機關認定之精神疾病，但不包括反社會人格違常者。本法於 2022-12-14 全文修正（2024-12-14 施行，第五章強制社區治療及強制住院治療自 2026-08-01 施行），條次重新編排，現行第3條仍規定反社會人格違常者不包括在內，精神疾病範圍為精神病、精神官能症、物質使用障礙症（涵蓋酒癮、藥癮）及其他經認定之精神疾病，選項(C)仍正確。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020030'),('SW-111-1-28','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-02-19。本題比較各法專業人員陪同出庭之規定。家庭暴力防治法第13條（被害人得聲請個案輔導之社工人員、心理師陪同在場）、性侵害犯罪防治法第18條（考試時第15條，社會工作人員陪同在場）、家事事件法第11條（法院應通知主管機關指派社會工作人員陪同在場）均有規定，考試時至今仍存在。精神衛生法修正前後均無社會工作人員或其他專業人員陪同病人出庭之規定；2022-12-14 全文修正後，強制住院等事件由法官與專科醫師、病人權益促進團體代表之參審員組成合議庭審理（第67條），法院並得選任程序監理人（第70條），均非陪同出庭之規定，選項(C)仍為正確答案。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020030');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>11 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>11 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'8790a3e30db9207688804547b00bba03' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_6, count(*) FILTER (WHERE q.legal_status='changed') changed_5, count(*) total_11 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
